import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor tanh_forward(torch::Tensor x);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Vectorized tanh kernel operating on float4 chunks for coalesced memory access.
__global__ void tanh_kernel_vec4(const float4* __restrict__ X4,
                                  float4* __restrict__ Y4,
                                  int64_t N4)
{
  // Process multiple float4 chunks per thread (ILP) to better saturate
  // memory bandwidth by overlapping multiple in-flight loads/stores,
  // which is beneficial for this memory-bound elementwise kernel.
  const int UNROLL = 4;
  int64_t base = (int64_t)blockIdx.x * (int64_t)blockDim.x + (int64_t)threadIdx.x;
  int64_t stride = (int64_t)blockDim.x * (int64_t)gridDim.x;
  for (int64_t idx = base; idx < N4; idx += stride * UNROLL) {
    #pragma unroll
    for (int u = 0; u < UNROLL; ++u) {
      int64_t j = idx + (int64_t)u * stride;
      if (j < N4) {
        float4 v = __ldcs(&X4[j]);
        float4 r;
        r.x = tanhf(v.x);
        r.y = tanhf(v.y);
        r.z = tanhf(v.z);
        r.w = tanhf(v.w);
        __stcs(&Y4[j], r);
      }
    }
  }
}
// Scalar tail kernel for the remaining elements (N % 4 != 0 case).
// Scalar tail kernel for the remaining elements (N % 4 != 0 case).
__global__ void tanh_kernel_tail(const float* __restrict__ X,
                                  float* __restrict__ Y,
                                  int64_t start,
                                  int64_t N)
{
  int64_t idx = start + (int64_t)blockIdx.x * (int64_t)blockDim.x + (int64_t)threadIdx.x;
  int64_t stride = (int64_t)blockDim.x * (int64_t)gridDim.x;
  for (; idx < N; idx += stride) {
    __stcs(&Y[idx], tanhf(__ldcs(&X[idx])));
  }
}
torch::Tensor tanh_forward(torch::Tensor x)
{
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  auto y = torch::empty_like(x_c);

  int64_t N  = x_c.numel();
  int64_t N4 = N / 4;
  int64_t tail_start = N4 * 4;
  int64_t tail_count = N - tail_start;

  const float* x_ptr = x_c.data_ptr<float>();
  float* y_ptr = y.data_ptr<float>();

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  if (N4 > 0) {
    const int threads = 256;
    int device = 0;
    cudaGetDevice(&device);
    int numSMs = 0;
    cudaDeviceGetAttribute(&numSMs, cudaDevAttrMultiProcessorCount, device);
    int maxBlocksPerSM = 0;
    cudaOccupancyMaxActiveBlocksPerMultiprocessor(&maxBlocksPerSM, tanh_kernel_vec4, threads, 0);
    int64_t optimal_blocks = (int64_t)numSMs * (int64_t)((maxBlocksPerSM > 0) ? maxBlocksPerSM : 1);
    int64_t blocks = (N4 + threads - 1) / threads;
    if (optimal_blocks > 0 && blocks > optimal_blocks) blocks = optimal_blocks;
    if (blocks < 1) blocks = 1;
    tanh_kernel_vec4<<<(unsigned)blocks, threads, 0, stream>>>(
        reinterpret_cast<const float4*>(x_ptr),
        reinterpret_cast<float4*>(y_ptr),
        N4);
  }
  if (tail_count > 0) {
    const int threads = 512;
    int64_t blocks = (tail_count + threads - 1) / threads;
    tanh_kernel_tail<<<(unsigned)blocks, threads, 0, stream>>>(
        x_ptr, y_ptr, tail_start, N
    );
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "tanh_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

tanh_ext = load_inline(
    name="cute_tanh_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["tanh_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a Tanh activation using a custom CUTE/CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = tanh_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.tanh_forward(x)

